package.run:
$ErrorActionPreference = "Stop"
function Resolve-ClawRouterPackageId([string] $packageId) {
  switch ($packageId) {
    "linux-debian-x64-server-deb" { return "linux-x64-service" }
    "linux-debian-arm64-server-deb" { return "linux-arm64-service" }
    "linux-x64-server-tar-gz" { return "linux-x64-archive" }
    "linux-arm64-server-tar-gz" { return "linux-arm64-archive" }
    "windows-x64-server-msi" { return "windows-x64-service" }
    "windows-arm64-server-msi" { return "windows-arm64-service" }
    "windows-x64-server-zip" { return "windows-x64-archive" }
    "windows-arm64-server-zip" { return "windows-arm64-archive" }
    "macos-x64-server-pkg" { return "macos-x64-service" }
    "macos-arm64-server-pkg" { return "macos-arm64-service" }
    "macos-x64-server-tar-gz" { return "macos-x64-archive" }
    "macos-arm64-server-tar-gz" { return "macos-arm64-archive" }
    "linux-debian-x64-desktop-deb" { return "linux-x64-desktop" }
    "linux-debian-arm64-desktop-deb" { return "linux-arm64-desktop" }
    "windows-x64-desktop-msi" { return "windows-x64-desktop" }
    "windows-arm64-desktop-msi" { return "windows-arm64-desktop" }
    "macos-x64-desktop-pkg" { return "macos-x64-desktop" }
    "macos-arm64-desktop-pkg" { return "macos-arm64-desktop" }
    default { throw "Unsupported SDKWork package id $packageId" }
  }
}
$legacyPackageId = Resolve-ClawRouterPackageId $env:SDKWORK_PACKAGE_ID
if ($env:SDKWORK_PACKAGE_FORMAT -in @("deb", "pkg", "msi")) {
  node scripts/build-claw-router-native-installer.mjs --package-id $legacyPackageId --version $env:SDKWORK_PACKAGE_VERSION --staging-root dist/install-package-staging --output-dir dist/install-packages --json
} else {
  node scripts/build-claw-router-install-package.mjs --package-id $legacyPackageId --version $env:SDKWORK_PACKAGE_VERSION --staging-root dist/install-package-staging --output-dir dist/install-packages --json
}

$ErrorActionPreference = "Stop"
switch ($env:SDKWORK_PACKAGE_PROFILE) {
  'cloud-config' { pnpm gateway:cloud:bundle }
  default { Write-Host "Skipping cloud gateway config bundle for profile $($env:SDKWORK_PACKAGE_PROFILE)" }
}

validate.run:
$ErrorActionPreference = "Stop"
function Resolve-ClawRouterPackageId([string] $packageId) {
  switch ($packageId) {
    "linux-debian-x64-server-deb" { return "linux-x64-service" }
    "linux-debian-arm64-server-deb" { return "linux-arm64-service" }
    "linux-x64-server-tar-gz" { return "linux-x64-archive" }
    "linux-arm64-server-tar-gz" { return "linux-arm64-archive" }
    "windows-x64-server-msi" { return "windows-x64-service" }
    "windows-arm64-server-msi" { return "windows-arm64-service" }
    "windows-x64-server-zip" { return "windows-x64-archive" }
    "windows-arm64-server-zip" { return "windows-arm64-archive" }
    "macos-x64-server-pkg" { return "macos-x64-service" }
    "macos-arm64-server-pkg" { return "macos-arm64-service" }
    "macos-x64-server-tar-gz" { return "macos-x64-archive" }
    "macos-arm64-server-tar-gz" { return "macos-arm64-archive" }
    "linux-debian-x64-desktop-deb" { return "linux-x64-desktop" }
    "linux-debian-arm64-desktop-deb" { return "linux-arm64-desktop" }
    "windows-x64-desktop-msi" { return "windows-x64-desktop" }
    "windows-arm64-desktop-msi" { return "windows-x64-desktop" }
    "macos-x64-desktop-pkg" { return "macos-x64-desktop" }
    "macos-arm64-desktop-pkg" { return "macos-arm64-desktop" }
    default { throw "Unsupported SDKWork package id $packageId" }
  }
}
function Resolve-ClawRouterArtifactId([string] $legacyPackageId) {
  $parts = $legacyPackageId -split "-"
  if ($parts.Length -ne 3) { throw "Invalid legacy Claw Router package id $legacyPackageId" }
  if ($parts[2] -eq "service") { return "$($parts[0])-$($parts[1])-server" }
  return $legacyPackageId
}
$legacyPackageId = Resolve-ClawRouterPackageId $env:SDKWORK_PACKAGE_ID
$legacyArtifactId = Resolve-ClawRouterArtifactId $legacyPackageId
$pattern = "clawrouter-$legacyArtifactId-$env:SDKWORK_PACKAGE_VERSION.$env:SDKWORK_PACKAGE_FORMAT"
$file = Get-ChildItem -Path "dist/install-packages" -File |
  Where-Object { $_.Name -like $pattern -and $_.Name -notlike "*.manifest.json" -and $_.Name -notlike "install-packages-manifest*.json" } |
  Select-Object -First 1
if (-not $file) { throw "Missing built install package artifact matching $pattern for $env:SDKWORK_PACKAGE_ID" }
node scripts/validate-claw-router-install-artifacts.mjs --package-id $legacyPackageId --artifact-path $file.FullName --version $env:SDKWORK_PACKAGE_VERSION

$ErrorActionPreference = "Stop"
switch ($env:SDKWORK_PACKAGE_PROFILE) {
  'cloud-config' { pnpm gateway:cloud:bundle:validate }
  default { Write-Host "Skipping cloud gateway config bundle validation for profile $($env:SDKWORK_PACKAGE_PROFILE)" }
}
